32	/// Paths to configuration files in priority order (later overrides earlier).
33	///
34	/// Merge order:
35	/// 1. Remote base configs (from `extends:`)
36	/// 2. User global config (`~/.bivvy/config.yml`)
37	/// 3. Project config (`.bivvy/config.yml`)
38	/// 4. Split-file steps (`.bivvy/steps/*.yml`)
39	/// 5. Split-file workflows (`.bivvy/workflows/*.yml`)
40	/// 6. Local overrides (`.bivvy/config.local.yml`)
41	#[derive(Debug, Clone)]
42	pub struct ConfigPaths {
43	    /// Remote base config (if extends: is used)
44	    pub extends: Vec<PathBuf>,
45	
46	    /// User's global config: ~/.bivvy/config.yml
47	    pub user_global: Option<PathBuf>,
48	
49	    /// Project config: .bivvy/config.yml
50	    pub project: Option<PathBuf>,
51	
52	    /// Split-file step definitions: .bivvy/steps/*.yml
53	    pub split_steps: Vec<PathBuf>,
54	
55	    /// Split-file workflow definitions: .bivvy/workflows/*.yml
56	    pub split_workflows: Vec<PathBuf>,
57	
58	    /// Local overrides: .bivvy/config.local.yml
59	    pub project_local: Option<PathBuf>,
60	}
