152	    /// Check if any project config exists.
153	    ///
154	    /// Returns true if `.bivvy/config.yml` exists OR if any split-file
155	    /// steps/workflows are present.
156	    pub fn has_project_config(&self) -> bool {
157	        self.project.is_some() || !self.split_steps.is_empty() || !self.split_workflows.is_empty()
158	    }
159	
160	    /// Whether any split files were discovered.
161	    pub fn has_split_files(&self) -> bool {
162	        !self.split_steps.is_empty() || !self.split_workflows.is_empty()
163	    }
164	}
